head.b:skin:
:root{
  --bg:#050505;
  --bg2:#090909;
  --panel:#101010;
  --line:#252525;
  --line2:#1c1c1c;
  --red:#e50914;
  --red2:#ff1c27;
  --white:#f3f3f0;
  --muted:#8e8e8e;
  --max:1320px;
}

*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{
  margin:0;
  background:var(--bg);
  color:var(--white);
  font-family:Arial,Helvetica,sans-serif;
}
a{color:inherit;text-decoration:none}
img{max-width:100%;display:block}
button,input,select{font:inherit}

.tgg-site{
  min-height:100vh;
  background:var(--bg);
}

.tgg-wrap{
  width:min(var(--max),calc(100% - 34px));
  margin:0 auto;
}

/* HEADER */
.tgg-header{
  position:sticky;
  top:0;
  z-index:1000;
  background:rgba(5,5,5,.92);
  border-bottom:1px solid var(--line2);
  backdrop-filter:blur(14px);
}
.tgg-header-row{
  width:min(var(--max),calc(100% - 34px));
  min-height:78px;
  margin:0 auto;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:24px;
}
.tgg-logo{
  display:flex;
  flex-direction:column;
  line-height:.88;
  flex:none;
}
.tgg-logo-main{
  font-weight:950;
  font-size:22px;
  letter-spacing:-.07em;
  text-transform:uppercase;
}
.tgg-logo-main span{color:var(--red)}
.tgg-logo-sub{
  margin-top:7px;
  color:#777;
  font-size:8px;
  font-weight:900;
  letter-spacing:.34em;
}
.tgg-nav{
  display:flex;
  align-items:center;
  gap:24px;
}
.tgg-nav a{
  color:#c7c7c7;
  font-size:10px;
  font-weight:900;
  letter-spacing:.09em;
  text-transform:uppercase;
}
.tgg-nav a:hover{color:#fff}
.tgg-nav .join{
  padding:10px 13px;
  background:var(--red);
  border:1px solid var(--red);
  border-radius:4px;
  color:#fff;
}
.tgg-menu{
  display:none;
  width:42px;
  height:42px;
  padding:8px;
  background:transparent;
  border:1px solid #333;
  border-radius:4px;
  cursor:pointer;
}
.tgg-menu span{
  display:block;
  height:2px;
  margin:5px 0;
  background:#fff;
}
.tgg-mobile{
  display:none;
  width:min(var(--max),calc(100% - 34px));
  margin:0 auto;
  padding:0 0 14px;
}
.tgg-mobile a{
  display:block;
  padding:12px 0;
  border-top:1px solid var(--line2);
  font-size:10px;
  font-weight:900;
  letter-spacing:.09em;
  text-transform:uppercase;
}

/* HOMEPAGE */
.tgg-home{
  background:var(--bg);
}

.tgg-hero{
  position:relative;
  min-height:720px;
  overflow:hidden;
  border-bottom:1px solid var(--line2);
  background:#090909;
}
.tgg-hero-art{
  position:absolute;
  inset:0;
  background:
    radial-gradient(circle at 78% 22%,rgba(229,9,20,.20),transparent 27%),
    radial-gradient(circle at 68% 50%,rgba(255,255,255,.05),transparent 25%),
    linear-gradient(120deg,#0a0a0a,#161616);
  background-position:center;
  background-size:cover;
  transition:transform .7s ease;
}
.tgg-hero:hover .tgg-hero-art{transform:scale(1.018)}
.tgg-hero-art:after{
  content:"";
  position:absolute;
  inset:0;
  background:
    linear-gradient(90deg,
      rgba(0,0,0,.98) 0%,
      rgba(0,0,0,.86) 36%,
      rgba(0,0,0,.28) 71%,
      rgba(0,0,0,.52) 100%),
    linear-gradient(180deg,
      rgba(0,0,0,.12) 26%,
      rgba(0,0,0,.95) 100%);
}
.tgg-hero-inner{
  position:relative;
  z-index:2;
  min-height:720px;
  display:flex;
  align-items:flex-end;
  padding:80px 0 56px;
}
.tgg-hero-copy{
  width:min(720px,74%);
}
.tgg-eyebrow{
  display:flex;
  align-items:center;
  gap:8px;
  color:#fff;
  font-size:10px;
  font-weight:900;
  letter-spacing:.18em;
  text-transform:uppercase;
}
.tgg-eyebrow:before{
  content:"";
  width:28px;
  height:2px;
  background:var(--red);
}
.tgg-hero h1{
  margin:16px 0 11px;
  font-size:clamp(58px,8.6vw,122px);
  line-height:.79;
  letter-spacing:-.075em;
  font-weight:950;
  text-transform:uppercase;
}
.tgg-hero h1 .red{color:var(--red)}
.tgg-description{
  max-width:570px;
  color:#c8c8c8;
  font-size:14px;
  line-height:1.65;
}
.tgg-meta{
  display:flex;
  flex-wrap:wrap;
  gap:8px 14px;
  margin:18px 0 22px;
  color:#a1a1a1;
  font-size:10px;
  font-weight:900;
  letter-spacing:.09em;
  text-transform:uppercase;
}
.tgg-meta b{color:#fff}
.tgg-actions{
  display:flex;
  gap:9px;
  flex-wrap:wrap;
}
.tgg-btn{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  min-height:45px;
  padding:0 17px;
  border-radius:4px;
  border:1px solid #4a4a4a;
  background:rgba(0,0,0,.34);
  color:#fff;
  font-size:10px;
  font-weight:900;
  letter-spacing:.1em;
  text-transform:uppercase;
  cursor:pointer;
  backdrop-filter:blur(8px);
}
.tgg-btn.red{
  background:var(--red);
  border-color:var(--red);
}
.tgg-btn.red:hover{background:var(--red2)}
.tgg-dots{
  display:flex;
  gap:6px;
  margin-top:22px;
}
.tgg-dots i{
  display:block;
  width:18px;
  height:2px;
  background:#777;
}
.tgg-dots i.active{
  width:34px;
  background:var(--red);
}

/* FEATURE CARDS */
.tgg-feature-grid{
  display:grid;
  grid-template-columns:repeat(3,1fr);
  gap:12px;
  margin-top:14px;
}
.tgg-feature{
  position:relative;
  min-height:142px;
  padding:20px;
  background:linear-gradient(145deg,#131313,#0c0c0c);
  border:1px solid var(--line2);
  transition:.2s ease;
}
.tgg-feature:hover{
  transform:translateY(-3px);
  border-color:#3d3d3d;
}
.tgg-feature .eyebrow-small{
  color:var(--red);
  font-size:9px;
  font-weight:900;
  letter-spacing:.14em;
  text-transform:uppercase;
}
.tgg-feature h3{
  margin:10px 0 6px;
  font-size:17px;
  text-transform:uppercase;
}
.tgg-feature p{
  margin:0;
  max-width:85%;
  color:#8b8b8b;
  font-size:11px;
  line-height:1.45;
}
.tgg-feature .arrow{
  position:absolute;
  right:18px;
  bottom:17px;
  color:#fff;
  font-size:15px;
}

/* SECTIONS */
.tgg-section{padding-top:46px}
.tgg-head{
  display:flex;
  justify-content:space-between;
  align-items:end;
  gap:18px;
  margin-bottom:16px;
}
.tgg-head h2{
  margin:0;
  font-size:29px;
  line-height:1;
  letter-spacing:-.05em;
  text-transform:uppercase;
}
.tgg-head h2 span{color:var(--red)}
.tgg-head a{
  color:#bcbcbc;
  font-size:10px;
  font-weight:900;
  letter-spacing:.1em;
  text-transform:uppercase;
}

/* SEARCH */
.tgg-search{
  display:flex;
  gap:9px;
  margin:0 0 10px;
}
.tgg-search input,
.tgg-search select{
  padding:12px 13px;
  color:#fff;
  background:#0b0b0b;
  border:1px solid #2b2b2b;
  border-radius:4px;
  outline:none;
}
.tgg-search input{flex:1}
.tgg-search input:focus,
.tgg-search select:focus{border-color:#555}
.tgg-count{
  color:#666;
  font-size:10px;
}

/* RELEASE CARDS */
.tgg-release-grid{
  display:grid;
  grid-template-columns:repeat(5,minmax(0,1fr));
  gap:12px;
  margin-top:14px;
}
.tgg-release{
  overflow:hidden;
  background:#0c0c0c;
  border:1px solid var(--line2);
  border-radius:5px;
  transition:.2s ease;
}
.tgg-release:hover{
  transform:translateY(-3px);
  border-color:#3b3b3b;
}
.tgg-art{
  position:relative;
  aspect-ratio:1/1.07;
  background:#161616;
  overflow:hidden;
}
.tgg-art img{
  width:100%;
  height:100%;
  object-fit:cover;
  transition:transform .3s ease;
}
.tgg-release:hover .tgg-art img{transform:scale(1.04)}
.tgg-play{
  position:absolute;
  right:9px;
  bottom:9px;
  width:36px;
  height:36px;
  border:1px solid rgba(255,255,255,.18);
  border-radius:50%;
  background:rgba(0,0,0,.76);
  color:#fff;
  cursor:pointer;
}
.tgg-play:hover{
  background:var(--red);
  border-color:var(--red);
}
.tgg-card-meta{padding:11px 11px 13px}
.tgg-card-title{
  margin:0;
  font-size:12px;
  font-weight:900;
  line-height:1.15;
  text-transform:uppercase;
}
.tgg-card-artist{
  margin-top:5px;
  color:#808080;
  font-size:9px;
  font-weight:800;
  text-transform:uppercase;
}
.tgg-card-genre{
  margin-top:7px;
  color:var(--red);
  font-size:8px;
  font-weight:900;
  letter-spacing:.12em;
  text-transform:uppercase;
}

/* WHY */
.tgg-why{
  margin-top:46px;
  padding:29px 0 25px;
  border-top:1px solid var(--line2);
  border-bottom:1px solid var(--line2);
}
.tgg-why h2{
  margin:0 0 23px;
  text-align:center;
  font-size:28px;
  letter-spacing:-.04em;
  text-transform:uppercase;
}
.tgg-why h2 span{color:var(--red)}
.tgg-why-grid{
  display:grid;
  grid-template-columns:repeat(4,1fr);
}
.tgg-why-item{
  padding:10px 18px;
  text-align:center;
  border-right:1px solid var(--line2);
}
.tgg-why-item:last-child{border-right:0}
.tgg-why-icon{
  margin-bottom:8px;
  color:var(--red);
  font-size:22px;
}
.tgg-why-item h3{
  margin:0 0 5px;
  font-size:11px;
  text-transform:uppercase;
}
.tgg-why-item p{
  margin:0;
  color:#777;
  font-size:9px;
  line-height:1.5;
}

/* CTA */
.tgg-cta{
  margin-top:30px;
  padding:30px;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:20px;
  border:1px solid var(--line2);
  background:
    radial-gradient(circle at 82% 20%,rgba(229,9,20,.18),transparent 29%),
    linear-gradient(145deg,#131313,#0c0c0c);
}
.tgg-cta h2{
  margin:0 0 6px;
  font-size:25px;
  text-transform:uppercase;
}
.tgg-cta p{
  margin:0;
  color:#888;
  font-size:11px;
}

/* PLAYER */
.tgg-player{
  position:fixed;
  left:0;
  right:0;
  bottom:0;
  z-index:99999;
  display:none;
  background:rgba(10,10,10,.97);
  border-top:1px solid #333;
  box-shadow:0 -8px 25px rgba(0,0,0,.5);
  backdrop-filter:blur(14px);
}
.tgg-player.show{display:block}
.tgg-player-inner{
  width:min(var(--max),calc(100% - 22px));
  min-height:56px;
  margin:0 auto;
  display:flex;
  align-items:center;
  gap:9px;
}
.tgg-player button{
  min-width:40px;
  min-height:36px;
  border:1px solid #444;
  border-radius:4px;
  background:#111;
  color:#fff;
  cursor:pointer;
}
.tgg-player .now{
  width:240px;
  color:#fff;
  font-size:10px;
  font-weight:900;
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
  text-transform:uppercase;
}
.tgg-player audio{width:100%}

/* FOOTER */
.tgg-footer{
  margin-top:34px;
  padding:38px 0 28px;
  border-top:1px solid var(--line2);
  background:#050505;
}
.tgg-footer-inner{
  width:min(var(--max),calc(100% - 34px));
  margin:0 auto;
}
.tgg-footer-top{
  display:flex;
  justify-content:space-between;
  gap:20px;
  align-items:flex-end;
}
.tgg-footer-brand{
  font-size:20px;
  font-weight:950;
  letter-spacing:-.05em;
  text-transform:uppercase;
}
.tgg-footer-brand span{color:var(--red)}
.tgg-footer-tag{
  margin-top:7px;
  color:#707070;
  font-size:8px;
  font-weight:900;
  letter-spacing:.26em;
}
.tgg-footer-links{
  display:flex;
  flex-wrap:wrap;
  gap:16px;
}
.tgg-footer-links a{
  color:#a2a2a2;
  font-size:9px;
  font-weight:900;
  letter-spacing:.08em;
  text-transform:uppercase;
}
.tgg-footer-links a:hover{color:#fff}
.tgg-footer-bottom{
  display:flex;
  justify-content:space-between;
  gap:18px;
  margin-top:22px;
  padding-top:14px;
  border-top:1px solid var(--line2);
  color:#666;
  font-size:8px;
  font-weight:800;
  letter-spacing:.08em;
  text-transform:uppercase;
}

/* RESPONSIVE */
@media(max-width:1050px){
  .tgg-release-grid{grid-template-columns:repeat(4,minmax(0,1fr))}
}
@media(max-width:860px){
  .tgg-nav{display:none}
  .tgg-menu{display:block}
  .tgg-feature-grid{grid-template-columns:1fr}
  .tgg-release-grid{grid-template-columns:repeat(3,minmax(0,1fr))}
  .tgg-why-grid{grid-template-columns:repeat(2,1fr)}
  .tgg-why-item:nth-child(2){border-right:0}
  .tgg-why-item:nth-child(n+3){border-top:1px solid var(--line2)}
}
@media(max-width:620px){
  .tgg-wrap{width:min(var(--max),calc(100% - 20px))}
  .tgg-header-row{width:min(var(--max),calc(100% - 20px))}
  .tgg-mobile{width:min(var(--max),calc(100% - 20px))}
  .tgg-hero,.tgg-hero-inner{min-height:560px}
  .tgg-hero-copy{width:100%}
  .tgg-hero-inner{padding:50px 0 34px}
  .tgg-hero h1{font-size:58px}
  .tgg-search{flex-direction:column}
  .tgg-release-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
  .tgg-why-grid{grid-template-columns:1fr}
  .tgg-why-item{border-right:0!important;border-top:1px solid var(--line2)}
  .tgg-why-item:first-child{border-top:0}
  .tgg-cta{flex-direction:column;align-items:flex-start}
  .tgg-footer-top,.tgg-footer-bottom{flex-direction:column;align-items:flex-start}
  .tgg-player .now{display:none}
}

.tgg-nav a.active-page,.tgg-mobile a.active-page{color:#fff}

b:includable.script:
    (function() {
      var items = ;
      var msgs = ;
      var config = ;

// 
      var cursor = null;
      if (items && items.length > 0) {
        cursor = parseInt(items[items.length - 1].timestamp) + 1;
      }

      var bodyFromEntry = function(entry) {
        var text = (entry &&
                    ((entry.content && entry.content.$t) ||
                     (entry.summary && entry.summary.$t))) ||
            '';
        if (entry && entry.gd$extendedProperty) {
          for (var k in entry.gd$extendedProperty) {
            if (entry.gd$extendedProperty[k].name == 'blogger.contentRemoved') {
              return '<span class="deleted-comment">' + text + '</span>';
            }
          }
        }
        return text;
      }

      var parse = function(data) {
        cursor = null;
        var comments = [];
        if (data && data.feed && data.feed.entry) {
          for (var i = 0, entry; entry = data.feed.entry[i]; i++) {
            var comment = {};
            // comment ID, parsed out of the original id format
            var id = /blog-(\d+).post-(\d+)/.exec(entry.id.$t);
            comment.id = id ? id[2] : null;
            comment.body = bodyFromEntry(entry);
            comment.timestamp = Date.parse(entry.published.$t) + '';
            if (entry.author && entry.author.constructor === Array) {
              var auth = entry.author[0];
              if (auth) {
                comment.author = {
                  name: (auth.name ? auth.name.$t : undefined),
                  profileUrl: (auth.uri ? auth.uri.$t : undefined),
                  avatarUrl: (auth.gd$image ? auth.gd$image.src : undefined)
                };
              }
            }
            if (entry.link) {
              if (entry.link[2]) {
                comment.link = comment.permalink = entry.link[2].href;
              }
              if (entry.link[3]) {
                var pid = /.*comments\/default\/(\d+)\?.*/.exec(entry.link[3].href);
                if (pid && pid[1]) {
                  comment.parentId = pid[1];
                }
              }
            }
            comment.deleteclass = 'item-control blog-admin';
            if (entry.gd$extendedProperty) {
              for (var k in entry.gd$extendedProperty) {
                if (entry.gd$extendedProperty[k].name == 'blogger.itemClass') {
                  comment.deleteclass += ' ' + entry.gd$extendedProperty[k].value;
                } else if (entry.gd$extendedProperty[k].name == 'blogger.displayTime') {
                  comment.displayTime = entry.gd$extendedProperty[k].value;
                }
              }
            }
            comments.push(comment);
          }
        }
        return comments;
      };

      var paginator = function(callback) {
        if (hasMore()) {
          var url = config.feed + '?alt=json&v=2&orderby=published&reverse=false&max-results=50';
          if (cursor) {
            url += '&published-min=' + new Date(cursor).toISOString();
          }
          window.bloggercomments = function(data) {
            var parsed = parse(data);
            cursor = parsed.length < 50 ? null
                : parseInt(parsed[parsed.length - 1].timestamp) + 1
            callback(parsed);
            window.bloggercomments = null;
          }
          url += '&callback=bloggercomments';
          var script = document.createElement('script');
          script.type = 'text/javascript';
          script.src = url;
          document.getElementsByTagName('head')[0].appendChild(script);
        }
      };
      var hasMore = function() {
        return !!cursor;
      };
      var getMeta = function(key, comment) {
        if ('iswriter' == key) {
          var matches = !!comment.author
              && comment.author.name == config.authorName
              && comment.author.profileUrl == config.authorUrl;
          return matches ? 'true' : '';
        } else if ('deletelink' == key) {
          return config.baseUri + '/comment/delete/'
               + config.blogId + '/' + comment.id;
        } else if ('deleteclass' == key) {
          return comment.deleteclass;
        }
        return '';
      };

      var replybox = null;
      var replyUrlParts = null;
      var replyParent = undefined;

      var onReply = function(commentId, domId) {
        if (replybox == null) {
          // lazily cache replybox, and adjust to suit this style:
          replybox = document.getElementById('comment-editor');
          if (replybox != null) {
            replybox.height = '250px';
            replybox.style.display = 'block';
            replyUrlParts = replybox.src.split('#');
          }
        }
        if (replybox && (commentId !== replyParent)) {
          replybox.src = '';
          document.getElementById(domId).insertBefore(replybox, null);
          replybox.src = replyUrlParts[0]
              + (commentId ? '&parentID=' + commentId : '')
              + '#' + replyUrlParts[1];
          replyParent = commentId;
        }
      };

      var hash = (window.location.hash || '#').substring(1);
      var startThread, targetComment;
      if (/^comment-form_/.test(hash)) {
        startThread = hash.substring('comment-form_'.length);
      } else if (/^c[0-9]+$/.test(hash)) {
        targetComment = hash.substring(1);
      }

      // Configure commenting API:
      var configJso = {
        'maxDepth': config.maxThreadDepth
      };
      var provider = {
        'id': config.postId,
        'data': items,
        'loadNext': paginator,
        'hasMore': hasMore,
        'getMeta': getMeta,
        'onReply': onReply,
        'rendered': true,
        'initComment': targetComment,
        'initReplyThread': startThread,
        'config': configJso,
        'messages': msgs
      };

      var render = function() {
        if (window.goog && window.goog.comments) {
          var holder = document.getElementById('comment-holder');
          window.goog.comments.render(holder, provider);
        }
      };

      // render now, or queue to render when library loads:
      if (window.goog && window.goog.comments) {
        render();
      } else {
        window.goog = window.goog || {};
        window.goog.comments = window.goog.comments || {};
        window.goog.comments.loadQueue = window.goog.comments.loadQueue || [];
        window.goog.comments.loadQueue.push(render);
      }
    })();
//

body.script:
//
(function(){

  var SUPABASE_URL = 'https://xsofowzvwetamhyuvlpj.supabase.co';
  var SUPABASE_ANON_KEY = 'sb_publishable_mJQg4LjW-9KsW5B1zzJH8Q_e-kA-bbv';

  var home = document.getElementById('tggReleaseGrid');
  if(!home || !window.supabase) return;

  if(SUPABASE_URL.indexOf('YOUR_') === 0 || SUPABASE_ANON_KEY.indexOf('YOUR_') === 0){
    home.innerHTML = '<div style="color:#777;padding:20px 0">Add your Supabase URL and publishable/anon key to load releases.</div>';
    return;
  }

  var db = window.supabase.createClient(SUPABASE_URL, SUPABASE_ANON_KEY);

  var heroArt = document.getElementById('tggHeroArt');
  var heroA = document.getElementById('tggHeroA');
  var heroB = document.getElementById('tggHeroB');
  var heroDescription = document.getElementById('tggHeroDescription');
  var heroMeta = document.getElementById('tggHeroMeta');
  var heroPlay = document.getElementById('tggHeroPlay');
  var heroTracklist = document.getElementById('tggHeroTracklist');

  var search = document.getElementById('tggSearch');
  var genre = document.getElementById('tggGenre');
  var count = document.getElementById('tggCount');

  var player = document.createElement('div');
  player.className = 'tgg-player';
  player.innerHTML =
    '<div class="tgg-player-inner">' +
      '<button type="button" id="tggClosePlayer">×</button>' +
      '<div class="now" id="tggNowPlaying">Now Playing</div>' +
      '<audio id="tggAudio" controls="controls" preload="none"></audio>' +
    '</div>';
  document.body.appendChild(player);

  var closePlayer = document.getElementById('tggClosePlayer');
  var audio = document.getElementById('tggAudio');
  var nowPlaying = document.getElementById('tggNowPlaying');

  var releases = [];

  function esc(value){
    var d=document.createElement('div');
    d.textContent=value || '';
    return d.innerHTML;
  }

  function firstTrack(item){
    var tracks=(item.tracks || []).filter(function(t){
      return !!t.id;
    }).sort(function(a,b){
      return (a.track_number || 0) - (b.track_number || 0);
    });
    return tracks[0] || null;
  }

  function play(trackId,title){
    if(!trackId || typeof window.tggSecureAudioUrl !== "function") return;
    window.tggSecureAudioUrl(trackId,"stream").then(function(url){
      audio.src=url;
      nowPlaying.textContent=title;
      player.className='tgg-player show';
      audio.play().catch(function(){});
    }).catch(function(err){ console.warn("TGG protected playback:",err); });
  }

  closePlayer.onclick=function(){
    audio.pause();
    player.className='tgg-player';
  };

  window.tggBloggerPlay=function(url,title){
    play(url,title);
  };

  function renderHero(item){
    if(!item) return;

    var words=(item.title || 'NO DAYS OFF').trim().split(/\s+/);

    if(words.length > 1){
      heroA.textContent=words.slice(0,-1).join(' ');
      heroB.textContent=words[words.length-1];
    }else{
      heroA.textContent=words[0];
      heroB.textContent='';
    }

    heroDescription.textContent=item.description || 'New independent music, fresh energy, and the next wave of artists.';

    var meta=[];
    if(item.artists && item.artists.stage_name){
      meta.push('<b>'+esc(item.artists.stage_name)+'</b>');
    }
    if(item.genre){
      meta.push(esc(item.genre));
    }
    if(item.release_date){
      meta.push(esc(item.release_date));
    }
    heroMeta.innerHTML=meta.join('<span>•</span>');

    if(item.cover_url){
      heroArt.style.backgroundImage="url('"+item.cover_url.replace(/'/g,"%27")+"')";
    }

    heroTracklist.href='/?view=mixtape&id='+encodeURIComponent(item.id);

    var track=firstTrack(item);

    heroPlay.onclick=function(){
      if(track){
        play(track.id,item.title+' — '+track.title);
      }else{
        window.location.href=heroTracklist.href;
      }
    };
  }

  function card(item){
    var track=firstTrack(item);
    var href='/?view=mixtape&id='+encodeURIComponent(item.id);

    var art = item.cover_url
      ? '<img src="'+esc(item.cover_url)+'" alt="'+esc(item.title)+'"/>'
      : '<div style="height:100%;display:flex;align-items:flex-end;padding:12px;background:linear-gradient(145deg,#242424,#0d0d0d)"><strong>'+esc(item.title)+'</strong></div>';

    return (
      '<article class="tgg-release">' +
        '<a class="tgg-art" href="'+href+'">' +
          art +
          (track
            ? '<button class="tgg-play" type="button" onclick="event.preventDefault();event.stopPropagation();window.tggBloggerPlay(\''+
              esc(track.id).replace(/'/g,"&#39;")+
              '\',\''+
              esc(item.title+' — '+track.title).replace(/'/g,"&#39;")+
              '\')">▶</button>'
            : '') +
        '</a>' +
        '<div class="tgg-card-meta">' +
          '<div class="tgg-card-title">'+esc(item.title)+'</div>' +
          '<div class="tgg-card-artist">'+esc(item.artists && item.artists.stage_name ? item.artists.stage_name : 'Unknown Artist')+'</div>' +
          (item.genre ? '<div class="tgg-card-genre">'+esc(item.genre)+'</div>' : '') +
        '</div>' +
      '</article>'
    );
  }

  function render(){
    var q=(search.value || '').trim().toLowerCase();
    var g=genre.value;

    var filtered=releases.filter(function(item){
      var title=(item.title || '').toLowerCase();
      var artist=(item.artists && item.artists.stage_name ? item.artists.stage_name : '').toLowerCase();
      return (!q || title.indexOf(q)!==-1 || artist.indexOf(q)!==-1) &&
             (!g || item.genre===g);
    });

    count.textContent=filtered.length+' published release'+(filtered.length===1?'':'s');

    if(!filtered.length){
      home.innerHTML='<div style="color:#777;padding:20px 0">No releases match your search.</div>';
      return;
    }

    home.innerHTML=filtered.slice(0,10).map(card).join('');
  }

  search.oninput=render;
  genre.onchange=render;

  db.from('mixtapes')
    .select(
      'id,title,genre,description,cover_url,release_date,featured,created_at,artists(id,stage_name),tracks(id,track_number,title)'
    )
    .eq('status','published')
    .order('created_at',{ascending:false})
    .then(function(result){

      if(result.error){
        console.error(result.error);
        home.innerHTML='<div style="color:#777;padding:20px 0">Unable to load releases.</div>';
        return;
      }

      releases=result.data || [];

      renderHero(releases[0]);

      var genres=[];
      releases.forEach(function(item){
        if(item.genre && genres.indexOf(item.genre)===-1){
          genres.push(item.genre);
        }
      });

      genres.sort();

      genre.innerHTML='<option value="">All Genres</option>'+
        genres.map(function(g){
          return '<option value="'+esc(g)+'">'+esc(g)+'</option>';
        }).join('');

      render();
    });

})();
