(function(){
  var path=window.location.pathname||'/';
  document.querySelectorAll('.tgg-nav a, .tgg-mobile a').forEach(function(a){
    var h=a.getAttribute('href')||'';
    if((path==='/'&&h==='/') ||
       (path==='/p/videos.html'&&h==='/p/videos.html') ||
       (path==='/p/interviews.html'&&h==='/p/interviews.html') ||
       (path==='/p/profiles.html'&&h==='/p/profiles.html')){
      a.classList.add('active-page');
    }
  });
})();
