(function(){
  const URL="https://xsofowzvwetamhyuvlpj.supabase.co";
  const KEY="sb_publishable_mJQg4LjW-9KsW5B1zzJH8Q_e-kA-bbv";
  const FN="tgg-audio-access";
  import("https://esm.sh/@supabase/supabase-js@2").then(function(mod){
    const client=mod.createClient(URL,KEY);
    window.supabaseClient=client;
    window.tggSecureAudioUrl=async function(trackId,mode){
      if(!trackId) throw new Error("Missing track ID");
      const session=await client.auth.getSession();
      const token=session&&session.data&&session.data.session&&session.data.session.access_token;
      if(!token) throw new Error("Please sign in to play protected audio.");
      const r=await fetch(URL+"/functions/v1/"+FN,{method:"POST",headers:{"Content-Type":"application/json","Authorization":"Bearer "+token,"apikey":KEY},body:JSON.stringify({track_id:String(trackId),mode:mode||"stream"})});
      let data=null; try{data=await r.json()}catch(e){}
      if(!r.ok || !data || data.ok!==true || !data.url) throw new Error(data&&data.error?data.error:"Protected audio access failed");
      if(!/^https:\/\//i.test(data.url) || /\/storage\/v1\/object\/public/i.test(data.url)) throw new Error("Invalid protected audio URL");
      return data.url;
    };
    window.TGG_SECURE_PLAYBACK={version:"final-theme-lock",protectedPlayback:true,noPublicAudio:true};
  }).catch(function(e){console.error("TGG secure playback bridge failed",e)});
})();
